type moderationPatternResolver struct{ *Resolver }

// Helper function to convert moderation event to alert
func convertModerationEventToAlert(event *streaming.InternalEvent) *model.ModerationAlert {
	if event == nil {
		return nil
	}

	// Extract moderation data from event
	var alert model.ModerationAlert
	alert.ID = event.ID
	alert.Timestamp = model.Time(event.Timestamp)
	alert.Handled = false
	alert.Confidence = 0.8 // Default confidence

	// Set severity based on event action
	switch event.Action {
	case streaming.ActionFlag:
		alert.Severity = model.ModerationSeverityHigh
		alert.SuggestedAction = model.ModerationActionRemove
	case streaming.ActionReview:
		alert.Severity = model.ModerationSeverityMedium
		alert.SuggestedAction = model.ModerationActionReview
	case streaming.ActionApprove:
		alert.Severity = model.ModerationSeverityLow
		alert.SuggestedAction = model.ModerationActionNone
	default:
		alert.Severity = model.ModerationSeverityLow
		alert.SuggestedAction = model.ModerationActionNone
	}

	// Extract matched text from metadata
	if event.Metadata != nil {
		if matchedText, ok := event.Metadata["matched_text"]; ok {
			alert.MatchedText = matchedText
		} else {
			alert.MatchedText = "Content flagged for review"
		}

		// Extract confidence if available
		if confidenceStr, ok := event.Metadata["confidence"]; ok {
			alert.Confidence = parseFloatOrZero(confidenceStr)
		}
	} else {
		alert.MatchedText = "Content flagged for review"
	}

	return &alert
}

// convertCostEventToAlert converts a cost event to a cost alert
func convertCostEventToAlert(event *streaming.InternalEvent, thresholdUSD float64) *model.CostAlert {
	if event == nil || event.Type != streaming.EventTypeCostAlert {
		return nil
	}

	alert := &model.CostAlert{
		ID:        event.ID,
		Timestamp: model.Time(event.Timestamp),
		Type:      "threshold_exceeded",
		Threshold: thresholdUSD,
		Message:   fmt.Sprintf("Cost threshold exceeded: %.2f USD", thresholdUSD),
	}

	// Extract cost details from metadata
	if event.Metadata != nil {
		if domain, ok := event.Metadata["domain"]; ok {
			alert.Domain = &domain
		}
		if costStr, ok := event.Metadata["cost_usd"]; ok {
			alert.Amount = parseFloatOrZero(costStr)
		} else {
			alert.Amount = thresholdUSD // Use threshold as amount if not specified
		}
	} else {
		alert.Amount = thresholdUSD
	}

	return alert
}

// convertCostEventToBudgetAlert converts a cost event to a budget alert
func convertCostEventToBudgetAlert(event *streaming.InternalEvent) *model.BudgetAlert {
	if event == nil {
		return nil
	}

	alert := &model.BudgetAlert{
		ID:         event.ID,
		Timestamp:  model.Time(event.Timestamp),
		Domain:     "localhost", // Default domain
		AlertLevel: model.AlertLevelWarning,
	}

	// Extract budget details from metadata
	if event.Metadata != nil {
		if domain, ok := event.Metadata["domain"]; ok {
			alert.Domain = domain
		}
		if budgetStr, ok := event.Metadata["budget_usd"]; ok {
			alert.BudgetUsd = parseFloatOrZero(budgetStr)
		}
		if spentStr, ok := event.Metadata["spent_usd"]; ok {
			alert.SpentUsd = parseFloatOrZero(spentStr)
		}

		// Calculate percentage
		if alert.BudgetUsd > 0 {
			alert.PercentUsed = (alert.SpentUsd / alert.BudgetUsd) * 100
		}

		// Set alert level based on percentage
		if alert.PercentUsed >= 90 {
			alert.AlertLevel = model.AlertLevelCritical
		} else if alert.PercentUsed >= 75 {
			alert.AlertLevel = model.AlertLevelWarning
		} else {
			alert.AlertLevel = model.AlertLevelInfo
		}

		// Check for projected overspend
		if projectedStr, ok := event.Metadata["projected_overspend"]; ok {
			overspend := parseFloatOrZero(projectedStr)
			alert.ProjectedOverspend = &overspend
		}
	}

	return alert
}

// convertHealthEventToFederationUpdate converts a health event to federation update
func convertHealthEventToFederationUpdate(event *streaming.InternalEvent) *model.FederationHealthUpdate {
	if event == nil {
		return nil
	}

	update := &model.FederationHealthUpdate{
		Domain:         "unknown",
		Timestamp:      model.Time(event.Timestamp),
		PreviousStatus: model.InstanceHealthStatusUnknown,
		CurrentStatus:  model.InstanceHealthStatusUnknown,
		Issues:         []*model.HealthIssue{},
	}

	// Extract health details from metadata
	if event.Metadata != nil {
		if domain, ok := event.Metadata["domain"]; ok {
			update.Domain = domain
		}

		// Parse previous and current status
		if prevStatus, ok := event.Metadata["previous_status"]; ok {
			update.PreviousStatus = parseHealthStatus(prevStatus)
		}
		if currStatus, ok := event.Metadata["current_status"]; ok {
			update.CurrentStatus = parseHealthStatus(currStatus)
		}

		// Extract health issues if any
		if issueType, ok := event.Metadata["issue_type"]; ok {
			issue := &model.HealthIssue{
				Type:        issueType,
				Description: event.Metadata["issue_description"],
				Severity:    model.IssueSeverityMedium,
			}

			// Parse severity if available
			if sev, ok := event.Metadata["issue_severity"]; ok {
				switch sev {
				case "high":
					issue.Severity = model.IssueSeverityHigh
				case "low":
					issue.Severity = model.IssueSeverityLow
				default:
					issue.Severity = model.IssueSeverityMedium
				}
			}

			update.Issues = append(update.Issues, issue)
		}
	}

	return update
}

// parseHealthStatus converts a string to InstanceHealthStatus
func parseHealthStatus(status string) model.InstanceHealthStatus {
	switch status {
	case HealthStatusHealthy:
		return model.InstanceHealthStatusHealthy
	case "degraded", HealthStatusWarning:
		return model.InstanceHealthStatusWarning
	case HealthStatusCritical:
		return model.InstanceHealthStatusCritical
	case "offline":
		return model.InstanceHealthStatusOffline
	default:
		return model.InstanceHealthStatusUnknown
	}
}

// parseFloatOrZero parses a string to float64, returns 0 on error
func parseFloatOrZero(s string) float64 {
	var f float64
	_, _ = fmt.Sscanf(s, "%f", &f)
	return f
}
